// C++23 fixture adapter/comparator. Decimal/status expectations are generated by
// the existing independent std::from_chars count_tsv_reference.cpp, not this
// plumbing adapter. Input and oracle log paths must be distinct.
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>
#include <cstdint>
#include <stdexcept>
using I=std::int64_t;
std::string load(const char*p){std::ifstream f(p);if(!f)throw std::runtime_error("missing input");std::ostringstream s;s<<f.rdbuf();return s.str();}
void replace_all(std::string&s,const std::string&a,const std::string&b){std::size_t p=0;while((p=s.find(a,p))!=std::string::npos){s.replace(p,a.size(),b);p+=b.size();}}
int main(int argc,char**argv){try{
 if(argc==4&&std::string(argv[1])=="--adapt"){
  std::string s=load(argv[2]);const bool into=std::string(argv[3])=="into";
  if(!into&&std::string(argv[3])!="legacy")return 2;
  const auto begin=s.find("fn drive("),end=s.find("\nfn boundaries()",begin);
  if(begin==std::string::npos||end==std::string::npos)return 3;
  auto drive=s.substr(begin,end-begin);const auto close=drive.rfind("\n}");if(close==std::string::npos)return 3;
  drive.insert(close,"\n let actual_status:i64=state.status;let actual_position:i64=state.position\n println(\"TOKEN {} {} {} {} {}\",samples,chunk,actual_status,actual_position,rows)\n");
  if(into){
   replace_all(drive,"var state=count_tsv_new(samples)","var state=count_tsv_new(samples)\n var slot=count_tsv_feed_slot()");
   replace_all(drive,"let r=count_tsv_feed(&!state,&part,n)","let ignored:i64=count_tsv_feed_into(&!state,&part,n,&!slot)");
   replace_all(drive,"r.","slot.");
   replace_all(drive,"let eof=count_tsv_finish(&!state)","let ignored_eof:i64=count_tsv_finish_into(&!state,&!slot)");replace_all(drive,"eof.","slot.");
   replace_all(drive,"let again=count_tsv_finish(&!state)","let ignored_again:i64=count_tsv_finish_into(&!state,&!slot)");replace_all(drive,"again.","slot.");
  }
  s.replace(begin,end-begin,drive);replace_all(s,"with Mut,Div,Panic {","with Mut,Div,Panic,IO {");
  if(into){const auto p=s.find("\nuse ");if(p==std::string::npos)return 3;s.insert(p,"\nuse genomics::io::count_tsv::{count_tsv_feed_slot,count_tsv_feed_into,count_tsv_finish_into}\n");}
  std::cout<<s;return 0;
 }
 if(argc==4&&std::string(argv[1])=="--check"){
  struct Expected{I status,position,rows;};std::vector<Expected> cases;std::istringstream summary(load(argv[2]));std::string line;
  while(std::getline(summary,line)){if(line.rfind("parse\t",0)!=0)continue;std::istringstream s(line);std::string tag,name;I index;Expected e{};if(!(s>>tag>>index>>name>>e.status>>e.position>>e.rows)||index!=I(cases.size()))return 3;cases.push_back(e);}
  if(cases.empty()){return 3;}std::istringstream actual(load(argv[3]));
  for(const auto&e:cases)for(I chunk:{1,2,3,7,256}){
   if(!std::getline(actual,line)){std::cerr<<"token completion\n";return 9;}
   std::istringstream s(line);std::string tag,extra;I samples,c,status,position,rows;
   if(!(s>>tag>>samples>>c>>status>>position>>rows)||s>>extra||tag!="TOKEN"||c!=chunk)return 4;
   if(status!=e.status||position!=e.position||rows!=e.rows){std::cerr<<"token protocol status/position/rows\n";return 8;}
   if((status==1)==(samples>=1&&samples<=8))return 8;
  }
  if(!std::getline(actual,line)||line!="GENOMICS_COUNT_TSV_PASS"||std::getline(actual,line)){std::cerr<<"token completion\n";return 9;}
  std::cout<<"TOKEN_FROM_CHARS_REFERENCE_PASS cases="<<cases.size()<<" chunks=1,2,3,7,256\n";return 0;
 }
 if(argc==4&&std::string(argv[1])=="--bench"){
  const I n=std::stoll(argv[2]);if(n!=100000&&n!=1000000)return 2;
  std::istringstream s(load(argv[3]));std::string tag,marker,extra;I declared,rows,position,total,finished,status;
  if(!(s>>tag>>declared>>rows>>position>>total>>finished>>status>>marker)||s>>extra||tag!="TOKEN_BENCH"||marker!="TOKEN_BENCH_PASS")return 4;
  if(declared!=n||rows!=n||position!=2*n||total!=n||finished!=1||status!=0){std::cerr<<"token benchmark rows/position/checksum\n";return 8;}
  std::cout<<"TOKEN_BENCH_REFERENCE_PASS tokens="<<n<<" byte_calls="<<2*n<<"\n";return 0;
 }
 return 2;
}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 3;}}
